8	/**
9	 * Create-time uniqueness guard for {@code POST /owners}: the single duplicate check. It rejects a
10	 * request whose whole {@link OwnerIdentity identityKey} equals an existing owner's, with a 409 via
11	 * {@link DuplicateIdentityException}. This one key subsumes the former separate telephone, email
12	 * and household guards: a collision requires the normalised telephone, the email and the household
13	 * to all match, so (for example) two members of one household with different telephones are both
14	 * allowed.
15	 *
16	 * <p>Runs after {@link NormalizeOwnerTelephone} and {@link NormalizeOwnerEmail} so the request's
17	 * telephone and email are already in their stored (canonical) forms, and before {@link BuildOwner}.
18	 * A new owner's {@code householdId} is not assigned until later in the pipeline, so the request's
19	 * household component is empty here; it is compared against each existing owner's stored key.
20	 */
21	public class CheckOwnerIdentityUnique {
22	
23	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
24	            throws DuplicateIdentityException {
25	        String identityKey = OwnerIdentity.key(request.getTelephone(), request.getEmail(), null);
26	        for (Owner existing : ownerRepository.findAll()) {
27	            if (identityKey.equals(OwnerIdentity.of(existing))) {
28	                throw new DuplicateIdentityException(identityKey);
29	            }
30	        }
31	    }
32	}
